package com.rustypayments;

import java.time.*;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Set;

public class BankCalendar implements PaymentCalendar {

    private static final ZoneId BANK_ZONE = ZoneId.of("Europe/Warsaw");
    private static final LocalTime CUT_OFF_TIME = LocalTime.of(16, 0);

    private static final Set<MonthDay> HOLIDAYS = Set.of(
            MonthDay.of(Month.JANUARY, 1),
            MonthDay.of(Month.JANUARY, 6),
            MonthDay.of(Month.MAY, 1),
            MonthDay.of(Month.MAY, 3),
            MonthDay.of(Month.AUGUST, 15),
            MonthDay.of(Month.NOVEMBER, 1),
            MonthDay.of(Month.NOVEMBER, 11),
            MonthDay.of(Month.DECEMBER, 25),
            MonthDay.of(Month.DECEMBER, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate ld = parseLocalDate(date);
        DayOfWeek dow = ld.getDayOfWeek();
        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) {
            return false;
        }
        return !HOLIDAYS.contains(MonthDay.from(ld));
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime zdt = parseZonedDateTime(submittedAt);
        LocalDate ld = zdt.toLocalDate();
        LocalTime lt = zdt.toLocalTime();

        if (isBusinessDay(ld.toString()) && !lt.isAfter(CUT_OFF_TIME)) {
            return ld.toString();
        }
        return nextBusinessDay(ld).toString();
    }

    @Override
    public String settlementDate(String submittedAt) {
        LocalDate processing = LocalDate.parse(processingDate(submittedAt));
        return nextBusinessDay(processing).toString();
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseLocalDate(dueDate);
        ZonedDateTime paidZdt = parseZonedDateTime(paidAt);
        LocalDate paidDate = paidZdt.toLocalDate();

        long diff = ChronoUnit.DAYS.between(due, paidDate);
        return (int) Math.max(0, diff);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate start = parseLocalDate(date);
        boolean isLastDay = start.getDayOfMonth() == start.lengthOfMonth();
        LocalDate result = start.plusMonths(months);
        if (isLastDay) {
            result = result.withDayOfMonth(result.lengthOfMonth());
        }
        return result.toString();
    }

    private LocalDate nextBusinessDay(LocalDate from) {
        LocalDate next = from.plusDays(1);
        while (!isBusinessDay(next.toString())) {
            next = next.plusDays(1);
        }
        return next;
    }

    private LocalDate parseLocalDate(String date) {
        if (date == null) throw new IllegalArgumentException("Date is null");
        try {
            return LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid date format: " + date);
        }
    }

    private ZonedDateTime parseZonedDateTime(String instant) {
        if (instant == null) throw new IllegalArgumentException("Instant is null");
        try {
            // OffsetDateTime is used first because the contract requires an offset
            return OffsetDateTime.parse(instant).atZoneSameInstant(BANK_ZONE);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid instant format: " + instant);
        }
    }
}

